// Collect the websites of column "website" into one list (one Actor run for the whole sheet).
const domains = $input.all()
  .map((item) => String(item.json.website ?? '').trim())
  .filter(Boolean);
if (domains.length === 0) throw new Error('No website found: add a column named "website" to the Websites tab.');
return [{ json: { domains } }];

// One row per website: e-mails, phones and social profiles as readable cells.
return $input.all().map(({ json: w }) => ({
  json: {
    website: w.domain,
    email: w.email ?? null,
    allEmails: (w.emails || []).join(', '),
    phones: (w.phones || []).join(', '),
    facebook: w.facebookUrl ?? null,
    instagram: w.instagramUrl ?? null,
    linkedin: w.linkedinUrl ?? null,
    x: w.xUrl ?? null,
    status: w.status,
    checkedAt: w.observedAt,
  },
}));
